"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["6277"],{6866(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>c,frontMatter:()=>r,contentTitle:()=>a,toc:()=>h,assets:()=>l});var s=JSON.parse('{"id":"m4-model-effort-cost/deep-dive","title":"Deep Dive: Dual FinOps \u2014 Two Budgets at Once","description":"The core lab taught you to measure one thing: what a Claude Code run costs. That is the agent\'s own operating cost \u2014 tokens turned into dollars, captured in the ledger. This page is about the trap that measurement quietly sets, and the discipline that avoids it.","source":"@site/docs/m4-model-effort-cost/deep-dive.md","sourceDirName":"m4-model-effort-cost","slug":"/m4-model-effort-cost/deep-dive","permalink":"/306-agentic-devops-claude/docs/m4-model-effort-cost/deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4,"title":"Deep Dive: Dual FinOps \u2014 Two Budgets at Once","sidebar_label":"Deep Dive (Part 2)"},"sidebar":"courseSidebar","previous":{"title":"Quiz: Model and Cost Engineering","permalink":"/306-agentic-devops-claude/docs/m4-model-effort-cost/quiz"},"next":{"title":"Plan, Execute, Verify","permalink":"/306-agentic-devops-claude/docs/m5-plan-execute-verify/lesson"}}'),i=n(4848),o=n(8453);let r={sidebar_position:4,title:"Deep Dive: Dual FinOps \u2014 Two Budgets at Once",sidebar_label:"Deep Dive (Part 2)"},a="Deep Dive \u2014 Dual FinOps: Two Budgets at Once",l={},h=[{value:"The two budgets",id:"the-two-budgets",level:2},{value:"Why blurring them produces backwards decisions",id:"why-blurring-them-produces-backwards-decisions",level:2},{value:"Enterprise gateways and audit trails",id:"enterprise-gateways-and-audit-trails",level:2},{value:"The non-Claude routing exclusion",id:"the-non-claude-routing-exclusion",level:2},{value:"Where you&#39;ll use this",id:"where-youll-use-this",level:2}];function d(e){let t={admonition:"admonition",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"deep-dive--dual-finops-two-budgets-at-once",children:"Deep Dive \u2014 Dual FinOps: Two Budgets at Once"})}),"\n",(0,i.jsx)(t.p,{children:"The core lab taught you to measure one thing: what a Claude Code run costs. That is the agent's own operating cost \u2014 tokens turned into dollars, captured in the ledger. This page is about the trap that measurement quietly sets, and the discipline that avoids it."}),"\n",(0,i.jsxs)(t.p,{children:['The trap is treating "agent cost" as ',(0,i.jsx)(t.em,{children:"the"})," cost. It is one of two budgets an agentic ops team runs simultaneously, and they are not the same budget, not in size, not in who owns them, and not in how you should reason about them. Confuse them and you make exactly backwards decisions: you throttle a $0.30 agent run to protect a budget, and in doing so you let it miss a $2,800-a-month mistake in the infrastructure it was reviewing. The whole point of this page is to keep those two budgets separate in your head and in your tooling \u2014 because the moment they blur, cost engineering starts optimizing the wrong number."]}),"\n",(0,i.jsx)(t.h2,{id:"the-two-budgets",children:"The two budgets"}),"\n",(0,i.jsx)(t.p,{children:"Every time an agent does ops work, money moves in two independent places:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Target-system cost"})," \u2014 what the ",(0,i.jsx)(t.em,{children:"infrastructure the agent manages"})," costs. The EC2 instances, the RDS database, the NAT gateways, the S3 buckets. This is the big number, the one that has always been there, the one FinOps was invented for. When the agent reviews a Terraform plan, target-system cost is ",(0,i.jsx)(t.em,{children:"what the plan will cost to run in production"}),"."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Agent-operating cost"})," \u2014 what ",(0,i.jsx)(t.em,{children:"running the agent"})," costs. The API tokens the agent spends to do its reasoning, read the plan, and produce its finding. This is the new number, the one this course taught you to see, and it is usually small \u2014 cents to low dollars per run."]}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Analogy:"})," this is the difference between the cost of the building and the cost of the inspector. A building inspector might bill you $400 to walk a construction site. The building costs $4 million. You would never conflate the two \u2014 and you would certainly never skip the $400 inspection to \"save money\" when the thing it protects is $4 million. The inspector's fee and the building's cost are separate line items with wildly different magnitudes, and the entire economic case for the inspector is that a cheap inspection prevents an expensive mistake. Agent-operating cost is the inspector's fee. Target-system cost is the building."]}),"\n",(0,i.jsx)(t.p,{children:"Northstar makes the gap concrete. Its cost-estimate fixtures describe the same production estate two ways:"}),"\n",(0,i.jsx)(t.mermaid,{value:'flowchart LR\n    subgraph TARGET["Target-system cost (the building)"]\n      OVER["Oversized plan<br/>db.r6g.4xlarge RDS<br/><b>$3,148.97 / month</b>"]\n      GOOD["Right-sized plan<br/>db.r6g.large RDS<br/><b>$301.97 / month</b>"]\n    end\n    subgraph AGENT["Agent-operating cost (the inspector)"]\n      RUN["One reviewer run<br/>reads the plan, flags the oversize<br/><b>cents in tokens</b>"]\n    end\n    RUN --\x3e|"catches"| OVER\n    OVER --\x3e|"\u2192 becomes"| GOOD\n    style OVER fill:#ffebee,stroke:#c62828\n    style GOOD fill:#e8f5e9,stroke:#388e3c\n    style RUN fill:#e3f2fd,stroke:#1976d2'}),"\n",(0,i.jsxs)(t.p,{children:["The oversized plan costs ",(0,i.jsx)(t.strong,{children:"$3,148.97/month"}),"; the right-sized one costs ",(0,i.jsx)(t.strong,{children:"$301.97/month"}),". The difference \u2014 about ",(0,i.jsx)(t.strong,{children:"$2,847 every month"}),", roughly $34,000 a year \u2014 comes down almost entirely to one over-provisioned RDS instance class. A reviewer agent that reads the plan and flags the oversize costs a few cents in tokens to run. The return on that few cents is the entire annual difference. That is the whole argument for dual FinOps in one example: the cheap budget exists to protect the expensive one, and reasoning about the cheap budget in isolation misses the point of running the agent at all."]}),"\n",(0,i.jsx)(t.h2,{id:"why-blurring-them-produces-backwards-decisions",children:"Why blurring them produces backwards decisions"}),"\n",(0,i.jsx)(t.p,{children:"If you track only agent-operating cost, you will make the reviewer cheaper \u2014 smaller model, lower effort, tighter token budget \u2014 because that is the number you can see and it is the number your alert fires on. And a cheaper reviewer is more likely to miss the oversized RDS. You will have optimized a $0.30 line item into saving $0.20, at the cost of a $2,847/month miss. The agent's ledger will look great. The AWS bill will not."}),"\n",(0,i.jsx)(t.p,{children:"If you track only target-system cost \u2014 the traditional FinOps posture \u2014 you never notice that your agent fleet's own token spend is climbing, that a misconfigured effort setting has tripled the cost of every investigation, that an automated agent is looping and burning tokens on a task it will never finish. The infrastructure bill is under control; the agent bill is quietly running away."}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Analogy:"}),' it is trying to run a restaurant by watching only the food cost or only the labor cost. Watch only ingredients and you will understaff until the kitchen fails; watch only wages and you will let waste and spoilage eat the margin. They are different budgets with different owners (the chef vs the floor manager) and different failure modes, and you have to hold both at once. Neither number is "the cost." The health of the operation is in the ',(0,i.jsx)(t.em,{children:"relationship"})," between them."]}),"\n",(0,i.jsx)(t.p,{children:"The correct posture is to keep two separate budget lines with two separate owners and two separate alert paths:"}),"\n",(0,i.jsxs)(t.table,{children:[(0,i.jsx)(t.thead,{children:(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.th,{}),(0,i.jsx)(t.th,{children:"Target-system cost"}),(0,i.jsx)(t.th,{children:"Agent-operating cost"})]})}),(0,i.jsxs)(t.tbody,{children:[(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"What it measures"})}),(0,i.jsx)(t.td,{children:"Infrastructure the agent manages"}),(0,i.jsx)(t.td,{children:"Tokens the agent spends"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Typical magnitude"})}),(0,i.jsx)(t.td,{children:"Hundreds to thousands / month"}),(0,i.jsx)(t.td,{children:"Cents to dollars / run"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Who owns it"})}),(0,i.jsx)(t.td,{children:"Platform / FinOps, as always"}),(0,i.jsx)(t.td,{children:"The team running the agents (you)"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"How you track it"})}),(0,i.jsx)(t.td,{children:"Cost estimates, cloud billing, Terraform plan review"}),(0,i.jsx)(t.td,{children:"The Agent Run Ledger from the core lab"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Failure mode if ignored"})}),(0,i.jsx)(t.td,{children:"Over-provisioned resources, waste"}),(0,i.jsx)(t.td,{children:"Runaway token spend, wrong-tier defaults"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"What connects them"})}),(0,i.jsxs)(t.td,{children:["The agent's ",(0,i.jsx)(t.em,{children:"output"})," changes target cost; the agent's ",(0,i.jsx)(t.em,{children:"run"})," incurs operating cost"]}),(0,i.jsx)(t.td,{})]})]})]}),"\n",(0,i.jsxs)(t.p,{children:["The bottom row is the key relationship: an agent run has a small operating cost and, through its output, a potentially large effect on target cost. Cost engineering for agentic ops means optimizing agent-operating cost ",(0,i.jsx)(t.em,{children:"only where it does not degrade the agent's effect on target cost"})," \u2014 spend the cents where the cents protect the dollars."]}),"\n",(0,i.jsx)(t.h2,{id:"enterprise-gateways-and-audit-trails",children:"Enterprise gateways and audit trails"}),"\n",(0,i.jsx)(t.p,{children:"At team scale, the two budgets need enforcement and evidence, not just good intentions. Two mechanisms carry that weight."}),"\n",(0,i.jsxs)(t.p,{children:["An ",(0,i.jsx)(t.strong,{children:"enterprise gateway"})," sits between your agents and the model API \u2014 every request routes through it. Because it is on the path, it is the natural place to enforce the agent-operating budget centrally: per-team spend limits, per-user quotas, rate limits, an org-wide kill switch if spend spikes. Individual engineers configuring their own budgets (the core-lab approach) does not scale to an organization; a gateway makes the budget a policy the org enforces rather than a suggestion each person opts into."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Analogy:"})," the gateway is the corporate card with a spending policy attached, versus everyone expensing on personal cards and reconciling later. The personal-card model works for a handful of people and collapses at scale \u2014 no central view, no enforced limits, no way to cut off a runaway before the statement arrives. The corporate card enforces the policy at swipe time and gives finance one ledger. The gateway does the same for agent spend: one control point, one view, limits enforced before the tokens are spent rather than regretted after."]}),"\n",(0,i.jsxs)(t.p,{children:["The ",(0,i.jsx)(t.strong,{children:"audit trail"})," is the second mechanism, and it is the direct descendant of Module 3's provenance discipline. Every agent action should be traceable to a cost and an actor: which agent, which run, which model and effort, how many tokens, and \u2014 critically \u2014 ",(0,i.jsx)(t.em,{children:"why"}),', tied back to the task and the human who authorized it. This is the Agent Run Ledger, promoted from a local convenience to an organizational record. When someone asks "why did our agent spend spike in March," or "which team is driving the reviewer costs," or "did this agent have authority to run this expensive task," the audit trail answers from evidence. Without it, you are back to the contractor with no invoice \u2014 except now it is a fleet of contractors and the bill has three commas.']}),"\n",(0,i.jsx)(t.mermaid,{value:'flowchart TD\n    AGENTS["Agent fleet<br/>(many runs, many users)"] --\x3e|"every request"| GW["Enterprise gateway<br/>enforces per-team budgets,<br/>quotas, kill switch"]\n    GW --\x3e|"routes to"| API["Claude model API"]\n    GW --\x3e|"records every call"| AUDIT["Audit trail<br/>agent \xb7 run \xb7 model \xb7 effort \xb7<br/>tokens \xb7 cost \xb7 task \xb7 authoriser"]\n    AUDIT --\x3e Q["Answers: who spent what, why,<br/>and were they authorised?"]\n    style GW fill:#fff3e0,stroke:#f57c00\n    style AUDIT fill:#e8f5e9,stroke:#388e3c'}),"\n",(0,i.jsx)(t.h2,{id:"the-non-claude-routing-exclusion",children:"The non-Claude routing exclusion"}),"\n",(0,i.jsxs)(t.p,{children:["There is one property of Claude Code that changes the risk profile of this whole picture, and it is worth stating plainly because it removes a class of cost-and-compliance surprise that plagues provider-agnostic gateways: ",(0,i.jsx)(t.strong,{children:"Claude Code only routes to Claude models."})]}),"\n",(0,i.jsxs)(t.p,{children:["An enterprise gateway that fronts ",(0,i.jsx)(t.em,{children:"multiple"}),' model providers introduces a routing decision \u2014 which provider serves this request. That decision is a place where things go wrong: a misconfiguration silently routes production traffic to a different, cheaper (or more expensive) provider; sensitive data flows to a model with different data-handling terms than you audited; a "cost optimization" reroute quietly changes which model your reviewer actually runs on, and your careful staffing decisions evaporate because the request never reached the model you chose. The billing surprise and the compliance surprise are two faces of the same ungoverned routing seam.']}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Analogy:"})," it is the difference between a single-supplier contract and a spot-market buyer. The spot-market buyer chases the cheapest price per unit and, in exchange, never quite knows which supplier filled the last order, under what terms, with what quality \u2014 and reconciling the invoices is a forensic exercise. The single-supplier contract costs you the option of chasing the spot price, and buys you certainty: one supplier, known terms, predictable bills, a clean audit. Claude Code's Claude-only routing is the single-supplier contract. You give up multi-provider arbitrage; you get a routing seam that cannot silently send your agent's work \u2014 or your data \u2014 somewhere you did not choose."]}),"\n",(0,i.jsxs)(t.p,{children:["For dual FinOps specifically, the exclusion means your two budgets stay clean. Agent-operating cost is denominated in one provider's pricing, so a token count maps to a dollar figure unambiguously \u2014 no \"which provider served this\" asterisk on every ledger row. And the audit trail's ",(0,i.jsx)(t.em,{children:"why"})," is trustworthy, because there is no hidden routing layer that could have substituted a different model between your staffing decision and the actual execution. The model in the ledger is the model that ran."]}),"\n",(0,i.jsx)(t.admonition,{title:"The exclusion is a governance feature, not a limitation",type:"note",children:(0,i.jsxs)(t.p,{children:['It is tempting to read "only routes to Claude models" as a constraint you are working around. For a cost-and-compliance perspective it is the opposite: it is the removal of a whole category of ungoverned routing failure. You can ',(0,i.jsx)(t.em,{children:"choose"})," to run multiple providers behind your own gateway if your organization wants that \u2014 but then the routing seam, and its billing and compliance surprises, become yours to govern. Claude Code not doing it for you means it cannot do it ",(0,i.jsx)(t.em,{children:"to"})," you."]})}),"\n",(0,i.jsx)(t.h2,{id:"where-youll-use-this",children:"Where you'll use this"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Reviewing infrastructure changes (M11, M12)."})," When an agent reviews a Terraform plan or a Helm change, you are watching two budgets at once: the cents the review costs and the dollars the change will cost in production. The dual-FinOps framing is exactly how you justify paying for a capable reviewer \u2014 the agent-operating cost is trivial next to the target-system cost it protects."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Standing up an agent fleet (M9, M10, capstone)."})," The moment more than one person runs agents, per-user budgets and a shared audit trail stop being optional. You will reach for a gateway pattern to enforce the agent-operating budget centrally, and the ledger from the core lab becomes the org's audit trail."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Answering the finance question."}),' Eventually someone owns the "why did agent spend go up" conversation. The dual-budget model is how you have that conversation without conflating a token-spend blip with an infrastructure-cost blip \u2014 two numbers, two owners, two explanations.']}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Evaluating any model gateway."})," Whenever you consider a provider-agnostic routing layer, ask what the routing seam does to your billing clarity and your audit trail. The trade you are making \u2014 arbitrage flexibility for governance certainty \u2014 is exactly the Claude-only-routing trade, run in reverse."]}),"\n"]})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>a});var s=n(6540);let i={},o=s.createContext(i);function r(e){let t=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),s.createElement(o.Provider,{value:t},e.children)}}}]);